def top_unnominated(year):
    sub = df[(df['oscars_year'] == year) & (df['result'].isna())]
    if sub.empty:
        return None
    return sub.sort_values('count', ascending=False).iloc[0]

unnoms = []
for _, w in winners.iterrows():
    yr = w['oscars_year']
    t = top_unnominated(yr)
    if t is None:
        continue
    unnoms.append({
        'oscars_year': yr,
        'winner': w['winner_name'],
